package com.motionstudio.standalone;
import android.media.*;
import java.io.File;
import java.nio.ByteBuffer;
public final class Mp4Exporter {
 public static void export(File file,int w,int h,int fps,int seconds)throws Exception {
 MediaCodec codec=MediaCodec.createEncoderByType("video/avc");MediaFormat fmt=MediaFormat.createVideoFormat("video/avc",w,h);fmt.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420SemiPlanar);fmt.setInteger(MediaFormat.KEY_BIT_RATE,1200000);fmt.setInteger(MediaFormat.KEY_FRAME_RATE,fps);fmt.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,1);
 MediaMuxer mux=null;boolean started=false;int track=-1;try{codec.configure(fmt,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);codec.start();mux=new MediaMuxer(file.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();int frames=fps*seconds;int queued=0;boolean eos=false;long deadline=System.currentTimeMillis()+45000;while(System.currentTimeMillis()<deadline){if(!eos){int ix=codec.dequeueInputBuffer(10000);if(ix>=0){ByteBuffer b=codec.getInputBuffer(ix);if(b==null)throw new Exception("No input buffer");b.clear();if(queued<frames){byte[] yuv=frame(w,h,queued,frames);b.put(yuv);codec.queueInputBuffer(ix,0,yuv.length,queued*1000000L/fps,0);queued++;}else{codec.queueInputBuffer(ix,0,0,queued*1000000L/fps,MediaCodec.BUFFER_FLAG_END_OF_STREAM);eos=true;}}}int out=codec.dequeueOutputBuffer(info,10000);if(out==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){if(started)throw new Exception("Format changed twice");track=mux.addTrack(codec.getOutputFormat());mux.start();started=true;}else if(out>=0){ByteBuffer data=codec.getOutputBuffer(out);if(data!=null&&info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0){if(!started)throw new Exception("Muxer not started");data.position(info.offset);data.limit(info.offset+info.size);mux.writeSampleData(track,data,info);}boolean done=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(out,false);if(done)break;}}if(!started||file.length()==0)throw new Exception("No encoded samples");}finally{try{codec.stop();}catch(Exception ignored){}codec.release();if(mux!=null){if(started)try{mux.stop();}catch(Exception ignored){}mux.release();}}}
 static byte[] frame(int w,int h,int n,int total){byte[] b=new byte[w*h*3/2];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int wave=(int)(40*Math.sin((x+n*4)*.025));b[y*w+x]=(byte)(80+wave+(y*60/h));}for(int i=w*h;i<b.length;i+=2){b[i]=(byte)128;b[i+1]=(byte)(140+(int)(30*Math.sin(n*.1)));}return b;}
}
